import{_ as t,o as a,c as s,a2 as r}from"./chunks/framework.7nMnW4XS.js";const g=JSON.parse('{"title":"NASA reference anchors — surface-hotspots v2 redesign","description":"","frontmatter":{},"headers":[],"relativePath":"reference/surface-redesign-nasa-anchors.md","filePath":"reference/surface-redesign-nasa-anchors.md"}'),n={name:"reference/surface-redesign-nasa-anchors.md"};function i(o,e,l,c,h,d){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="nasa-reference-anchors-—-surface-hotspots-v2-redesign" tabindex="-1">NASA reference anchors — surface-hotspots v2 redesign <a class="header-anchor" href="#nasa-reference-anchors-—-surface-hotspots-v2-redesign" aria-label="Permalink to &quot;NASA reference anchors — surface-hotspots v2 redesign&quot;">​</a></h1><p><strong>Context:</strong> the secondary-deliverable inspiration anchor for Issue <a href="https://github.com/chipi/orrery/issues/283" target="_blank" rel="noreferrer">#283</a>. Originally lived at <code>/tmp/orrery-mockups-nasa/REFERENCE.md</code> for the Slice 0 visual-preview review, but <code>/tmp</code> doesn&#39;t persist across reboots. Re-homed under <code>docs/reference/</code> so the file survives.</p><p>The 12 photoshopped mockup frames are at <a href="./../mockups/surface-redesign/README"><code>docs/mockups/surface-redesign/</code></a> — those are the primary design contract. This file is the <em>why behind the design language</em>, anchored in two NASA reference families.</p><h2 id="two-distinct-reference-families-nasa-gets-right" tabindex="-1">Two distinct reference families NASA gets right <a class="header-anchor" href="#two-distinct-reference-families-nasa-gets-right" aria-label="Permalink to &quot;Two distinct reference families NASA gets right&quot;">​</a></h2><h3 id="a-image-extent-rectangles-—-perseverance-location-map-mars" tabindex="-1">A. Image-extent rectangles — Perseverance location map (Mars) <a class="header-anchor" href="#a-image-extent-rectangles-—-perseverance-location-map-mars" aria-label="Permalink to &quot;A. Image-extent rectangles — Perseverance location map (Mars)&quot;">​</a></h3><p><strong>Source:</strong> <a href="https://science.nasa.gov/mission/mars-2020-perseverance/location-map/" target="_blank" rel="noreferrer">https://science.nasa.gov/mission/mars-2020-perseverance/location-map/</a></p><p>The base map is a low/mid-res orbital mosaic. Higher-resolution HiRISE swaths sit on top as <strong>rectangular tiles bounded exactly by their actual image footprint</strong>. The rectangle shape <em>is</em> the data — HiRISE strips are physical instruments and rectangular by nature.</p><p>Decisions taken from this:</p><ul><li><strong>Rectangle = honest image footprint</strong> (replaces the v0.6/v0.7 circular <code>Tier 2</code> disc that encoded nothing geometric).</li><li><strong>Hard edges between layers are acceptable</strong> when the edge is meaningful — outside the rectangle = lower-res, inside = higher-res. No fade, no curvature illusion. Compare with the legacy dark CTX disc which felt like a sticker because the shape didn&#39;t mean anything.</li><li><strong>Pins inside the rectangle</strong> for waypoint events (sample tubes, drill sites) — tear-drop shape, agency-tinted, separate primitive from the imagery.</li><li><strong>Traverse polyline</strong> as a continuous bold line, distinct from waypoint pins.</li><li><strong>Scale bar always visible</strong> bottom-left, in km/miles. Lat/lon readout bottom-right.</li></ul><p>→ Implementation: Frames 04 / 05 / 10 / 11 of the mockup set (flat-patch with HUD) + <code>SurfaceFlatPatch.svelte</code> per ADR-062.</p><h3 id="b-region-of-interest-rectangles-—-lunar-south-pole-moonbase-plan" tabindex="-1">B. Region-of-interest rectangles — Lunar South Pole moonbase plan <a class="header-anchor" href="#b-region-of-interest-rectangles-—-lunar-south-pole-moonbase-plan" aria-label="Permalink to &quot;B. Region-of-interest rectangles — Lunar South Pole moonbase plan&quot;">​</a></h3><p><strong>Source:</strong> various NASA / JPL Artemis briefings (search &quot;NASA Artemis III candidate landing region map&quot; or the Shackleton Connecting Ridge graphic — public domain).</p><p>The map shows several named areas — <strong>Peak Near Shackleton Rim A</strong>, <strong>Connecting Ridge</strong>, <strong>Haworth</strong>, <strong>Malapert Massif</strong> — each as a <strong>translucent cyan quad</strong> with a label outside it. The rectangles are <em>semantic regions of interest</em>, not image footprints. They can overlap, they&#39;re named, they&#39;re conceptual.</p><p>Decisions taken from this:</p><ul><li><strong>Rectangle = named region</strong> (replaces the legacy point + circle radius pattern).</li><li><strong>Translucent fill + crisp border</strong> signals &quot;this area is interesting&quot; without occluding terrain.</li><li><strong>Label sits outside the rectangle</strong> with a clean connector or just proximity — not inside the shape.</li><li><strong>Multiple regions visible at once</strong> without occlusion problems, because they don&#39;t carry heavy iconography.</li></ul><p>→ Implementation: Frames 01 / 07 of the mockup set (planet-wide overview with multiple regions) + the <code>region_bounds</code> schema field per ADR-061.</p><h2 id="what-we-deliberately-do-that-nasa-doesn-t" tabindex="-1">What we deliberately do that NASA doesn&#39;t <a class="header-anchor" href="#what-we-deliberately-do-that-nasa-doesn-t" aria-label="Permalink to &quot;What we deliberately do that NASA doesn&#39;t&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>NASA&#39;s approach</th><th>Orrery&#39;s choice</th><th>Rationale</th></tr></thead><tbody><tr><td>Sphere ↔ flat</td><td>Flat 2D throughout</td><td>Sphere wide-zoom, flat patch at deep zoom (ADR-062)</td><td>Sphere preserves &quot;you&#39;re looking at a planet&quot; context at wide zoom; flat patch unlocks true-scale at deep zoom</td></tr><tr><td>Engineering 3D models</td><td>None on the map</td><td>Rendered at Tier 1; hidden once Tier-2 region is the active representation</td><td>Lets users explore the hardware silhouettes at mid-zoom; hides them at deep zoom where they&#39;d compete with the imagery</td></tr><tr><td>Marker scale</td><td>Same screen size at all zooms</td><td>True-world-scale floor (rover ~3 m, lander ~5 m) above a minimum-clickable threshold (4 px)</td><td>Develops a felt sense for how small the hardware is on the surface</td></tr><tr><td>Upsample warning</td><td>Accepts zoom-past-resolution as blur</td><td>Subtle vignette + microcopy &quot;approaching native pixel limit&quot;</td><td>Users don&#39;t read the blur as &quot;the planet is fuzzy&quot;</td></tr></tbody></table><h2 id="re-pull-commands-if-literal-annotated-composites-are-wanted-later" tabindex="-1">Re-pull commands (if literal annotated composites are wanted later) <a class="header-anchor" href="#re-pull-commands-if-literal-annotated-composites-are-wanted-later" aria-label="Permalink to &quot;Re-pull commands (if literal annotated composites are wanted later)&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Perseverance — 4 zoom levels (URLs approximate; check current location-map page)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/orrery-mockups-nasa/nasa-perseverance-z1.png</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;https://mars.nasa.gov/system/resources/detail_files/...png&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Lunar South Pole moonbase plan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/orrery-mockups-nasa/nasa-shackleton-ridge.png</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;https://www.nasa.gov/wp-content/uploads/2024/.../candidate-landing-regions.png&quot;</span></span></code></pre></div><p>Then annotate via the same Playwright/SVG pattern as the primary mockups (<code>scripts/mockups/render-surface-mockups.mjs</code>) — drop the NASA PNG as the background, overlay the Orrery-side mapping (&quot;our equivalent is Frame 04&quot;) in a corner.</p><p>For Slice 0 the primary 12 frames + this written reference were sufficient. Re-pull if a future redesign needs literal NASA composites.</p>`,22)])])}const m=t(n,[["render",i]]);export{g as __pageData,m as default};
